#include <vector>
#include <string>
#include <unordered_map>

struct TrieNode {
    std::unordered_map<int, TrieNode*> children;
    int cnt = 0;
};

class Solution {
public:
    long long countPrefixSuffixPairs(std::vector<std::string>& words) {
        long long ans = 0;
        TrieNode* root = new TrieNode();
        for (const auto& s : words) {
            TrieNode* cur = root;
            int len = s.size();
            for (int i = 0; i < len; ++i) {
                int key = (s[i] - 'a') * 26 + (s[len - 1 - i] - 'a');
                if (!cur->children.count(key)) cur->children[key] = new TrieNode();
                cur = cur->children[key];
                ans += cur->cnt;
            }
            cur->cnt++;
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    static class TrieNode {
        Map<Integer, TrieNode> children = new HashMap<>();
        int cnt = 0;
    }

    public long countPrefixSuffixPairs(String[] words) {
        long ans = 0;
        TrieNode root = new TrieNode();
        for (String s : words) {
            TrieNode cur = root;
            int len = s.length();
            for (int i = 0; i < len; ++i) {
                int key = (s.charAt(i) - 'a') * 26 + (s.charAt(len - 1 - i) - 'a');
                cur.children.putIfAbsent(key, new TrieNode());
                cur = cur.children.get(key);
                ans += cur.cnt;
            }
            cur.cnt++;
        }
        return ans;
    }
}

var countPrefixSuffixPairs = function(words) {
    let ans = 0;
    const root = { children: new Map(), cnt: 0 };
    for (const s of words) {
        let cur = root;
        const len = s.length;
        for (let i = 0; i < len; ++i) {
            const key = (s.charCodeAt(i) - 97) * 26 + (s.charCodeAt(len - 1 - i) - 97);
            if (!cur.children.has(key)) {
                cur.children.set(key, { children: new Map(), cnt: 0 });
            }
            cur = cur.children.get(key);
            ans += cur.cnt;
        }
        cur.cnt++;
    }
    return ans;
};
